/**
 * Get the attributes and values that were validated.
 *
 * @return array
 *
 * @throws \Illuminate\Validation\ValidationException
 */
public function validated()
{
    if (! $this->messages) {
        $this->passes();
    }

    throw_if($this->messages->isNotEmpty(), $this->exception, $this);

    $results = [];

    $missingValue = new stdClass;

    foreach ($this->getRules() as $key => $rules) {
        $value = data_get($this->getData(), $key, $missingValue);

        if ($this->excludeUnvalidatedArrayKeys &&
            in_array('array', $rules) &&
            $value !== null &&
            ! empty(preg_grep('/^'.preg_quote($key, '/').'\.+/', array_keys($this->getRules())))) {
            continue;
        }

        if ($value !== $missingValue) {
            Arr::set($results, $key, $value);
        }
    }

    return $this->replacePlaceholders($results);
}

/**
 * Validate a given attribute against a rule.
 *
 * @param  string  $attribute
 * @param  string  $rule
 * @return void
 */
protected function validateAttribute($attribute, $rule)
{
    $this->currentRule = $rule;

    [$rule, $parameters] = ValidationRuleParser::parse($rule);

    if ($rule === '') {
        return;
    }

    // First we will get the correct keys for the given attribute in case the field is nested in
    // an array. Then we determine if the given rule accepts other field names as parameters.
    // If so, we will replace any asterisks found in the parameters with the correct keys.
    if ($this->dependsOnOtherFields($rule)) {
        $parameters = $this->replaceDotInParameters($parameters);

        if ($keys = $this->getExplicitKeys($attribute)) {
            $parameters = $this->replaceAsterisksInParameters($parameters, $keys);
        }
    }

    $value = $this->getValue($attribute);

    // If the attribute is a file, we will verify that the file upload was actually successful
    // and if it wasn't we will add a failure for the attribute. Files may not successfully
    // upload if they are too large based on PHP's settings so we will bail in this case.
    if ($value instanceof UploadedFile && ! $value->isValid() &&
        $this->hasRule($attribute, array_merge($this->fileRules, $this->implicitRules))
    ) {
        return $this->addFailure($attribute, 'uploaded', []);
    }

    // If we have made it this far we will make sure the attribute is validatable and if it is
    // we will call the validation method with the attribute. If a method returns false the
    // attribute is invalid and we will add a failure message for this failing attribute.
    $validatable = $this->isValidatable($rule, $attribute, $value);

    if ($rule instanceof RuleContract) {
        return $validatable
                ? $this->validateUsingCustomRule($attribute, $value, $rule)
                : null;
    }

    $method = "validate{$rule}";

    $this->numericRules = $this->defaultNumericRules;

    if ($validatable && ! $this->$method($attribute, $value, $parameters, $this)) {
        $this->addFailure($attribute, $rule, $parameters);
    }
}

/**
 * Determine if the given rule depends on other fields.
 *
 * @param  string  $rule
 * @return bool
 */
protected function dependsOnOtherFields($rule)
{
    return in_array($rule, $this->dependentRules);
}

/**
 * Get the explicit keys from an attribute flattened with dot notation.
 *
 * E.g. 'foo.1.bar.spark.baz' -> [1, 'spark'] for 'foo.*.bar.*.baz'
 *
 * @param  string  $attribute
 * @return array
 */
protected function getExplicitKeys($attribute)
{
    $pattern = str_replace('\*', '([^\.]+)', preg_quote($this->getPrimaryAttribute($attribute), '/'));

    if (preg_match('/^'.$pattern.'/', $attribute, $keys)) {
        array_shift($keys);

        return $keys;
    }

    return [];
}

/**
 * Get the primary attribute name.
 *
 * For example, if "name.0" is given, "name.*" will be returned.
 *
 * @param  string  $attribute
 * @return string
 */
protected function getPrimaryAttribute($attribute)
{
    foreach ($this->implicitAttributes as $unparsed => $parsed) {
        if (in_array($attribute, $parsed, true)) {
            return $unparsed;
        }
    }

    return $attribute;
}

/**
 * Replace each field parameter which has an escaped dot with the dot placeholder.
 *
 * @param  array  $parameters
 * @return array
 */
protected function replaceDotInParameters(array $parameters)
{
    return array_map(function ($field) {
        return str_replace('\.', $this->dotPlaceholder, $field);
    }, $parameters);
}

/**
 * Replace each field parameter which has asterisks with the given keys.
 *
 * @param  array  $parameters
 * @param  array  $keys
 * @return array
 */
protected function replaceAsterisksInParameters(array $parameters, array $keys)
{
    return array_map(function ($field) use ($keys) {
        return vsprintf(str_replace('*', '%s', $field), $keys);
    }, $parameters);
}

/**
 * Determine if the attribute is validatable.
 *
 * @param  object|string  $rule
 * @param  string  $attribute
 * @param  mixed  $value
 * @return bool
 */
protected function isValidatable($rule, $attribute, $value)
{
    if (in_array($rule, $this->excludeRules)) {
        return true;
    }

    return $this->presentOrRuleIsImplicit($rule, $attribute, $value) &&
           $this->passesOptionalCheck($attribute) &&
           $this->isNotNullIfMarkedAsNullable($rule, $attribute) &&
           $this->hasNotFailedPreviousRuleIfPresenceRule($rule, $attribute);
}

/**
 * Determine if the field is present, or the rule implies required.
 *
 * @param  object|string  $rule
 * @param  string  $attribute
 * @param  mixed  $value
 * @return bool
 */
protected function presentOrRuleIsImplicit($rule, $attribute, $value)
{
    if (is_string($value) && trim($value) === '') {
        return $this->isImplicit($rule);
    }

    return $this->validatePresent($attribute, $value) ||
           $this->isImplicit($rule);
}

/**
 * Determine if a given rule implies the attribute is required.
 *
 * @param  object|string  $rule
 * @return bool
 */
protected function isImplicit($rule)
{
    return $rule instanceof ImplicitRule ||
           in_array($rule, $this->implicitRules);
}

/**
 * Determine if the attribute passes any optional check.
 *
 * @param  string  $attribute
 * @return bool
 */
protected function passesOptionalCheck($attribute)
{
    if (! $this->hasRule($attribute, ['Sometimes'])) {
        return true;
    }

    $data = ValidationData::initializeAndGatherData($attribute, $this->data);

    return array_key_exists($attribute, $data)
        || array_key_exists($attribute, $this->data);
}

/**
 * Determine if the attribute fails the nullable check.
 *
 * @param  string  $rule
 * @param  string  $attribute
 * @return bool
 */
protected function isNotNullIfMarkedAsNullable($rule, $attribute)
{
    if ($this->isImplicit($rule) || ! $this->hasRule($attribute, ['Nullable'])) {
        return true;
    }

    return ! is_null(Arr::get($this->data, $attribute, 0));
}

/**
 * Determine if it's a necessary presence validation.
 *
 * This is to avoid possible database type comparison errors.
 *
 * @param  string  $rule
 * @param  string  $attribute
 * @return bool
 */
protected function hasNotFailedPreviousRuleIfPresenceRule($rule, $attribute)
{
    return in_array($rule, ['Unique', 'Exists']) ? ! $this->messages->has($attribute) : true;
}

